#!/usr/bin/env python3
import requests
import gmpy2

# Server details
URL = 'http://crypto.chal.csaw.io:5000'

# Constants from server
N = int("00ab76f585834c3c2b7b7b2c8a04c66571539fa660d39762e338cd8160589f08e3d223744cb7894ea6b424ebab899983ff61136c8315d9d03aef12bd7c0486184945998ff80c8d3d59dcb0196fb2c37c43d9cbff751a0745b9d796bcc155cfd186a3bb4ff6c43be833ff1322693d8f76418a48a51f43d598d78a642072e9fff533", 16)
g = 2
k = 3

def test_A_value(username, A_value):
    try:
        data = {
            'username': username,
            'token1': str(A_value)
        }
        response = requests.post(URL, data=data)
        if response.status_code == 200:
            json_data = response.json()
            return json_data.get('nacl'), int(json_data.get('token2'))
        else:
            print(f"Error response: {response.text}")
            return None, None
    except Exception as e:
        print(f"Error for {username}: {str(e)}")
        return None, None

def test_and_compare(users, A_value, desc):
    print(f"\nTesting {desc}:")
    results = {}

    for user in users:
        salt, B = test_A_value(user, A_value)
        results[user] = {'salt': salt, 'B': B}
        print(f"{user}:")
        print(f"  Salt: {salt}")
        print(f"  B: {B}")

    # Compare B values
    if all(v['B'] is not None for v in results.values()):
        B1 = results[users[0]]['B']
        B2 = results[users[1]]['B']
        if B1 != 0 and B2 != 0:
            ratio = gmpy2.div(B1, B2) if B2 != 0 else "undefined"
            diff = B1 - B2
            print(f"\nB1/B2 ratio: {ratio}")
            print(f"B1-B2 difference: {diff}")
            # Check if difference is related to g
            if diff != 0:
                print(f"diff % g = {diff % g}")
                print(f"diff % N = {diff % N}")

def main():
    users = ['Jere', 'Lakisha']

    # Test case 1: A = N-1
    test_and_compare(users, N-1, "A = N-1")

    # Test case 2: A = g^2 mod N
    A_g2 = pow(g, 2, N)
    test_and_compare(users, A_g2, "A = g^2 mod N")

    # Test case 3: A = N-g
    test_and_compare(users, N-g, "A = N-g")

    # Additional test: A = g
    test_and_compare(users, g, "A = g")

if __name__ == '__main__':
    main()

